import React from 'react';

import { updateCurrentUserFields } from '@apps/Account/@services/user.service';
import { IUserProfileDTO } from '@apps/Account/@types/user.types';
import HelpInfo from '@components/HelpInfo';
import { getInputDate } from '@helpers/dateHelper';
import PohButton, { ButtonVariant } from '@ui-kit/Button';
import PohInput, { InputTypes } from '@ui-kit/Input';
import PohContainer from '@ui-kit/layout/Container';
import { showModal } from '@ui-kit/Modal';
import PohSelect from '@ui-kit/Select';

import inaturalist_instruction from './inaturalist_instruction.png';

type EditableUserProfileFields = 'name' | 'surname' | 'dob' | 'sex' | 'phone' | 'inaturalist_login';
type EditableUserProfile = Pick<IUserProfileDTO, EditableUserProfileFields>;

interface IEditProfileModalProps {
  data: EditableUserProfile;
  onSave: (d: Partial<EditableUserProfile>) => void;
  onCancel: () => void;
}

const EditProfileModal: React.FC<IEditProfileModalProps> = ({ data, onSave, onCancel }) => {
  const initData = {
    name: data.name,
    surname: data.surname,
    sex: data.sex,
    dob: data.dob,
    phone: data.phone,
    inaturalist_login: data.inaturalist_login ?? '',
  };
  const [modelData, setModelData] = React.useState<EditableUserProfile>(initData);
  const handleSave = async (e: React.FormEvent) => {
    e.preventDefault();
    const onlyChanges = Object.keys(modelData).reduce<Partial<EditableUserProfile>>((acc, key) => {
      const k = key as EditableUserProfileFields;
      if (initData[k] !== modelData[k])
        acc[k] = k === 'dob' ? getInputDate(new Date(modelData[k]), true) : modelData[k];
      return acc;
    }, {});
    await updateCurrentUserFields(onlyChanges);
    onSave({ ...onlyChanges });
  };

  function handleChange<k extends keyof EditableUserProfile>(fieldName: k) {
    return (value: EditableUserProfile[k]) =>
      setModelData((cur) => ({ ...cur, [fieldName]: value }));
  }

  return (
    <PohContainer
      as="form"
      onSubmit={handleSave}
      className="d-flex flex-column"
      style={{ gap: 12 }}
    >
      <PohInput
        label="Фамилия"
        placeholder="Федосеев"
        value={modelData.surname}
        maxLength={64}
        onChange={handleChange('surname')}
        required
      />
      <PohInput
        label="Имя"
        placeholder="Николай"
        value={modelData.name}
        maxLength={64}
        onChange={handleChange('name')}
        required
      />
      <PohInput
        label="Дата рождения"
        value={modelData.dob}
        maxLength={64}
        onChange={handleChange('dob')}
        required
        type={InputTypes.date}
      />
      <PohSelect
        options={[
          { value: '1', label: 'Мужской' },
          { value: '2', label: 'Женский' },
        ]}
        onChange={handleChange('sex')}
        allowEmpty={false}
        value={modelData.sex === '0' ? '2' : modelData.sex}
        label="Пол"
      />
      <PohInput
        label="Телефон (формат 79998887766)"
        type={InputTypes.tel}
        value={modelData.phone}
        maxLength={11}
        onChange={handleChange('phone')}
        required
        pattern="^[0-9]{11}$"
      />
      <PohInput
        label={
          <div className="d-flex">
            Username iNaturalist
            <HelpInfo className="ms-auto">
              Войдите в свой профиль на сайте{' '}
              <a href="" target="_blank">
                https://www.inaturalist.org/
              </a>{' '}
              и скопируйте имя пользователя
              <img src={inaturalist_instruction} width={350} />
            </HelpInfo>
          </div>
        }
        labelClassName="d-block"
        placeholder="Если надо"
        value={modelData.inaturalist_login}
        maxLength={254}
        onChange={handleChange('inaturalist_login')}
      />

      <footer className="mt-4 text-end">
        <PohButton variant={ButtonVariant.Secondary} onClick={onCancel}>
          Отмена
        </PohButton>{' '}
        &nbsp;
        <PohButton variant={ButtonVariant.Primary} type="submit">
          Сохранить
        </PohButton>
      </footer>
    </PohContainer>
  );
};

export default EditProfileModal;

export const editProfileInModal = (
  cur: IUserProfileDTO,
  cb: (up: Partial<EditableUserProfile>) => void,
) =>
  showModal({
    title: 'Редактирование профиля',
    children: (clos) => (
      <EditProfileModal
        data={cur}
        onCancel={clos}
        onSave={(up) => {
          cb(up);
          clos();
        }}
      />
    ),
  });
