import { get, handleApiError, post } from '@helpers/httpClient';

import { mapUserAllergyToBack, mapUserAllergyToFront } from '../@mappers/user.mappers';
import { IUserAllergies, UserAllergiesType } from '../@types/user.types';
import { IUserAllergiesDTO, IUserAllergyUpdateDTO } from '../@types/user.types.dto';

export const getUserAllergies = async (type?: UserAllergiesType) => {
  const res = await get('/ajax/users/allergies_list.php', type ? { type } : {}).then<
    IUserAllergiesDTO[]
  >(handleApiError);
  return res.map(mapUserAllergyToFront);
};

export const addUserAllergy = async (allergy: IUserAllergies) => {
  const data: IUserAllergyUpdateDTO = mapUserAllergyToBack(allergy);
  const res = await post('/ajax/users/allergies_add_or_edit.php', { ...data, id: 0 }).then<{
    id: number;
  }>(handleApiError);

  return res.id;
};

export const updateUserAllergy = async (allergy: IUserAllergies) => {
  const data: IUserAllergyUpdateDTO = mapUserAllergyToBack(allergy);
  const res = await post('/ajax/users/allergies_add_or_edit.php', data).then<{
    success: boolean;
  }>(handleApiError);

  return res.success;
};

export const deleteUserAllergy = async (id: IUserAllergyUpdateDTO['id']) => {
  const res = await post('/ajax/users/allergies_del.php', { id }).then<{
    success: boolean;
  }>(handleApiError);

  return res.success;
};
