import React from 'react';

import { mapFrontUserPhoneToBack } from '@apps/Account/@mappers/user.mappers';
import { addOrUpdateUserPhone } from '@apps/Account/@services/user.service';
import { IUserPhone } from '@apps/Account/@types/user.types';
import PohButton, { ButtonVariant } from '@ui-kit/Button';
import PohCheckbox from '@ui-kit/Checkbox';
import PohInput, { InputTypes } from '@ui-kit/Input';
import PohContainer from '@ui-kit/layout/Container';

interface IAddPhoneModalProps {
  data?: IUserPhone;
  onSave: (d: IUserPhone) => void;
  onCancel: () => void;
}

const AddPhoneModal: React.FC<IAddPhoneModalProps> = ({ data, onSave, onCancel }) => {
  const [modelData, setModelData] = React.useState<IUserPhone>(
    data ?? {
      id: 0,
      phone: '',
      is_contact: true,
      is_send_sms: true,
      sms_api_key: '',
    },
  );
  const handleSave = async (e: React.FormEvent) => {
    e.preventDefault();
    const { id = 0 } = await addOrUpdateUserPhone(mapFrontUserPhoneToBack(modelData));
    onSave({ ...modelData, id });
  };

  function handleChange<k extends keyof IUserPhone>(fieldName: k) {
    return (value: IUserPhone[k]) => setModelData({ ...modelData, [fieldName]: value });
  }

  return (
    <PohContainer as="form" onSubmit={handleSave}>
      <PohInput
        label="Телефон (формат 79998887766)"
        type={InputTypes.tel}
        value={modelData.phone}
        maxLength={11}
        onChange={handleChange('phone')}
        required
        pattern="^[0-9]{11}$"
      />
      <PohCheckbox
        onChange={handleChange('is_contact')}
        checked={modelData.is_contact}
        label="Контактный"
      />
      <div className="mb-3" />
      <PohInput
        label="API key"
        maxLength={255}
        value={modelData.sms_api_key}
        onChange={handleChange('sms_api_key')}
      />
      <PohCheckbox
        onChange={handleChange('is_send_sms')}
        checked={modelData.is_send_sms}
        label="Отправлять СМС"
      />
      <footer className="mt-4">
        <PohButton variant={ButtonVariant.Secondary} onClick={onCancel}>
          Отмена
        </PohButton>{' '}
        &nbsp;
        <PohButton variant={ButtonVariant.Primary} type="submit">
          Сохранить
        </PohButton>
      </footer>
    </PohContainer>
  );
};

export default AddPhoneModal;
