import React from 'react';

import { IUserPhone } from '@apps/Account/@types/user.types';
import { showModal } from '@ui-kit/Modal';

import AddPhoneModal from './components/AddPhoneModal';

export function editPhoneModal(data: IUserPhone, onSave: (data: IUserPhone) => void) {
  showModal({
    children: (closeHandler) => (
      <AddPhoneModal
        data={data}
        onSave={(newItem) => {
          onSave(newItem);
          closeHandler();
        }}
        onCancel={closeHandler}
      />
    ),
  });
}

export default { editPhoneModal };
