import React from 'react';

import { IMedicament } from '@apps/Medicaments/@types/medicaments.types';
import { getMedicamentsAsync } from '@apps/Medicaments/services/medicaments.services';
import PageLoader from '@components/PageLoader';
import PohAlert, { AlertVariant } from '@ui-kit/Alert';
import PohInput, { InputTypes } from '@ui-kit/Input';
import PohList from '@ui-kit/List';
import { showModal } from '@ui-kit/Modal';

interface IMedicamentSelectorProps {
  onSelect: (selected: IMedicament) => void;
}

const MedicamentSelector: React.FC<IMedicamentSelectorProps> = ({ onSelect }) => {
  const [q, setQ] = React.useState('');
  const [medicaments, setMedicaments] = React.useState<IMedicament[]>([]);
  const [isLoading, setIsLoading] = React.useState(false);
  const [err, setErr] = React.useState<Error>();

  React.useEffect(() => {
    const init = async () => {
      try {
        setIsLoading(true);
        const mm = await getMedicamentsAsync();
        setMedicaments(mm);
      } catch (e) {
        setErr(e as Error);
      } finally {
        setIsLoading(false);
      }
    };

    init();
  }, []);

  if (isLoading) return <PageLoader />;
  if (err) return <PohAlert variant={AlertVariant.Danger}>{err.message}</PohAlert>;

  return (
    <div>
      <div className="d-flex align-content-center">
        <PohInput
          className="mb-2"
          type={InputTypes.search}
          value={q}
          onChange={setQ}
          placeholder="Найти"
        />
      </div>
      <div style={{ overflowY: 'auto', minWidth: 400, maxHeight: 300 }}>
        <PohList
          data={medicaments
            .filter((s) => !q.length || s.name.toLowerCase().includes(q.toLowerCase()))
            .map((m) => ({
              key: m.id,
              content: (
                <div className="d-flex align-items-baseline" style={{ gap: 6, cursor: 'pointer' }}>
                  {m.name}
                </div>
              ),
              action: true,
              onClick: () => onSelect(m),
            }))}
        />
      </div>
    </div>
  );
};

export function selectMedicamentAsync(): Promise<IMedicament> {
  return new Promise((resolve) => {
    showModal({
      size: 'sm',
      title: 'Выбор медикамента',
      children: (closeHandler: () => void) => (
        <MedicamentSelector
          onSelect={(s) => {
            resolve(s);
            closeHandler();
          }}
        />
      ),
    });
  });
}
