import React from 'react';

import { IUserAllergies } from '@apps/Users/@types/user.types';
import Empty from '@ui-kit/Empty';
import PohList from '@ui-kit/List';

import UserAllergiesListItem from './UserAllergiesListItem';

interface IUserAllergiesListProps {
  data: IUserAllergies[];
  onChange?: (item: IUserAllergies) => void;
}

const UserAllergiesList: React.FC<IUserAllergiesListProps> = ({ data, onChange }) => {
  if (!data.length)
    return (
      <Empty style={{ height: 74, minHeight: 0 }}>
        Нет аллергий в этом разделе
        <br />
        <small>И это замечательно!</small>
      </Empty>
    );
  return (
    <PohList
      data={data.map((item) => {
        return {
          key: item.id,
          children: <UserAllergiesListItem data={item} onChange={onChange} />,
        };
      })}
    />
  );
};

export default UserAllergiesList;
