import React from 'react';

import HikingListTogether from '@apps/Users/components/HikingListTogether';
import { AuthContext } from '@contexts/AuthContext';

const ProfileTabHiking = () => {
  const authContext = React.useContext(AuthContext);
  if (!authContext.user) return null;
  return (
    <div className="p-3">
      <h3>Походы</h3>
      Список походов
      <HikingListTogether id_user={authContext.user.id} />
    </div>
  );
};

export default ProfileTabHiking;
