import React from 'react';

import { getUserAllergies } from '@apps/Users/@services/userAllergies.services';
import { IUserAllergies, UserAllergiesType } from '@apps/Users/@types/user.types';
import UserAllergiesList from '@apps/Users/components/UserAllergiesList';
import { editUserAllergy } from '@apps/Users/components/UserAllergiesList/UserAllergyEditModal';
import PageLoader from '@components/PageLoader';
import notificationHelper from '@helpers/notificationHelper';
import PohAlert, { AlertVariant } from '@ui-kit/Alert';
import PohButton from '@ui-kit/Button';
import PohCol from '@ui-kit/layout/Col';
import PohRow from '@ui-kit/layout/Row';

const ProfileTabAllergies = () => {
  const [isLoading, setIsLoading] = React.useState(true);
  const [err, setErr] = React.useState<Error>();
  const [data, setData] = React.useState<IUserAllergies[]>([]);

  React.useEffect(() => {
    const start = async () => {
      try {
        setIsLoading(true);
        const dt = await getUserAllergies();
        setData(dt);
      } catch (e) {
        setErr(e as Error);
      } finally {
        setIsLoading(false);
      }
    };

    start();
  }, []);

  if (isLoading) return <PageLoader />;
  if (err) return <PohAlert variant={AlertVariant.Danger}>{err.message}</PohAlert>;

  const handleAdd = (type: UserAllergiesType) => async () => {
    editUserAllergy(
      {
        id: 0,
        name: '',
        comment: '',
        created_at: new Date(),
        type,
        updated_at: null,
        medicament: null,
        product: null,
      },
      (up) => {
        notificationHelper.success('Добавлено');
        setData((cur) => [...cur, up]);
      },
    );
  };
  const handleChange = async (item: IUserAllergies) => {
    editUserAllergy(
      item,
      (up) => {
        notificationHelper.success('Изменено');
        setData((cur) => cur.map((x) => (x.id === up.id ? up : x)));
      },
      () => {
        notificationHelper.success('Удалено');
        setData((cur) => cur.filter((x) => x.id !== item.id));
      },
    );
  };

  return (
    <div className="mt-3">
      <h2>Аллергии </h2>
      <p>
        В этом разделе вы можете указать имеющиеся у вас аллергии. Это очень <strong>важно</strong>,
        т.к. наличие этой информации у организаторов похода, позволит сделать ваше пребывание в
        походе комфортным и безопасным
      </p>
      <small>
        <blockquote>
          <small>
            <strong>Аллергия</strong> — Повышенная чувствительность организма к некоторым веществам
            (аллергенам), вызывающим болезненное состояние (слезоточивость, появление красных пятен
            и т. п.).
          </small>
        </blockquote>
        <PohRow>
          <PohCol sm={4}>
            <h3>Лекарства</h3>
            <p>
              <small>
                Аллергия на лекарственные препараты. Крайне внимательно отнеситесь к заполнению
                этого раздела.
              </small>
            </p>
            <UserAllergiesList
              data={data.filter((x) => x.type === UserAllergiesType.Medicament)}
              onChange={handleChange}
            />
            <PohButton block className="mt-2" onClick={handleAdd(UserAllergiesType.Medicament)}>
              Добавить
            </PohButton>
          </PohCol>

          <PohCol sm={4}>
            <h3>Продукты питания</h3>
            <p>
              <small>
                Аллергия на продукты. Не то, что вам не нравится, а то от поедания чего у вас
                наблюдается аллергическая реакция
              </small>
            </p>
            <UserAllergiesList
              data={data.filter((x) => x.type === UserAllergiesType.Product)}
              onChange={handleChange}
            />
            <PohButton block className="mt-2" onClick={handleAdd(UserAllergiesType.Product)}>
              Добавить
            </PohButton>
          </PohCol>
          <PohCol sm={4}>
            <h3>Прочее</h3>
            <p>
              <small>Аллергия на прочие вещества. Например пыль, тополиный пух или кошки</small>
            </p>
            <UserAllergiesList
              data={data.filter((x) => x.type === UserAllergiesType.Other)}
              onChange={handleChange}
            />
            <PohButton block className="mt-2" onClick={handleAdd(UserAllergiesType.Other)}>
              Добавить
            </PohButton>
          </PohCol>
        </PohRow>
      </small>
    </div>
  );
};

export default ProfileTabAllergies;
